listRule:
// 1. UI USER, owner/admin: every NATS identity in the active organization.
//    Not members -- this collection holds signed identities, and creds_file
//    embeds the seed. Members get exactly one row, via branch 2.
(@request.auth.collectionName = "users" &&
 organization = @request.auth.current_organization &&
(@request.auth.memberships_via_user.organization ?= @request.auth.current_organization &&
 (@request.auth.memberships_via_user.role ?= "owner" || @request.auth.memberships_via_user.role ?= "admin"))) ||

// 2. UI USER, any role: the ONE identity linked to my own membership in the
//    active organization. The browser opens its NATS connection with these
//    credentials (ui/src/stores/nats.ts), so every role including dashboard needs
//    this -- and only ever its own row. Row-correlated: both conditions match
//    the same membership record.
(@request.auth.collectionName = "users" &&
 memberships_via_nats_user.user ?= @request.auth.id &&
 memberships_via_nats_user.organization ?= @request.auth.current_organization) ||

// 3. THING: a Thing sees ONLY the NATS user assigned to its 'nats_user' field
(@request.auth.collectionName = "things" &&
 things_via_nats_user.id ?= @request.auth.id) ||

// 4. SELF: if the NATS user authenticates directly, it sees its own record
(@request.auth.collectionName = "nats_users" &&
 id = @request.auth.id)

// NOTE: there is deliberately no leaf_nodes branch. An edge box gets its creds
// from GET /api/leaf/bootstrap (hooks/leaf_node_routes.go), which reads this
// collection with the app's own privileges and returns four named values. That
// keeps the edge's blast radius fixed regardless of how these rules evolve.

