createRule:
// Owner/admin only. Minting a NATS identity is a security operation: the
// permissions on the new record end up inside a JWT signed by the org account.
@request.auth.collectionName = "users" &&
@request.body.organization = @request.auth.current_organization &&
(@request.auth.memberships_via_user.organization ?= @request.auth.current_organization &&
 (@request.auth.memberships_via_user.role ?= "owner" || @request.auth.memberships_via_user.role ?= "admin"))

updateRule:
// Owner/admin only, scoped to the active org, and never re-pointable at another
// tenant. Members are excluded because publish_permissions here is copied into
// the signed JWT -- a member could otherwise self-grant publish ">".
//
// Rotating your OWN credentials does not go through this rule: it needs a
// single-field allowlist (regenerate, and nothing else), which a rule can only
// approximate with an :isset deny-list that silently opens up whenever a field
// is added. That is POST /api/me/nats-creds/rotate instead
// (hooks/credential_routes.go), which writes exactly one field and takes no
// record id.
@request.auth.collectionName = "users" &&
organization = @request.auth.current_organization &&
(@request.auth.memberships_via_user.organization ?= @request.auth.current_organization &&
 (@request.auth.memberships_via_user.role ?= "owner" || @request.auth.memberships_via_user.role ?= "admin")) &&
@request.body.organization:changed = false

deleteRule:
// Owner/admin only (mirrors updateRule). Deleting a NATS identity revokes a
// device's access, so it is not a member-level action.
@request.auth.collectionName = "users" &&
organization = @request.auth.current_organization &&
(@request.auth.memberships_via_user.organization ?= @request.auth.current_organization &&
 (@request.auth.memberships_via_user.role ?= "owner" || @request.auth.memberships_via_user.role ?= "admin"))

