listRule:
// If a Thing is authenticating as itself (e.g. via SDK), it only sees its own record.
// If a User is authenticating, they see all things belonging to their active organization.
// A leaf node mirrors all things in its own organization.
(@request.auth.collectionName = "things" && id = @request.auth.id) || 
(@request.auth.collectionName = "users" && organization = @request.auth.current_organization) || 
(@request.auth.collectionName = "leaf_nodes" && organization = @request.auth.organization)

