createRule:
// Only users (not things) can create records, in their own active organization.
// Members may add inventory; only owner/admin may attach a NATS or Nebula
// identity to it, or set the active flag.
//
// nats_user / nebula_host are owner/admin only: a Thing can read the credential
//    of its own linked identity, so a member able to re-point those relations at a
//    privileged identity and then authenticate as the Thing would have a
//    credential-theft path.
//
// active is owner/admin only for the same reason delete is: taking a device off
//    the network revokes its NATS identity (hooks/active_flag.go). Members create
//    and edit inventory; disabling it is a management action.
//
// The member branch names the roles it admits. Restricting the FIELDS without
//    naming the ROLE let `dashboard` -- the least privileged role, which has no inventory
//    authority at all -- create and edit Things.
@request.auth.collectionName = "users" &&
@request.body.organization = @request.auth.current_organization &&
(
  // Owner/admin: may assign the NATS / Nebula identity links.
  (@request.auth.memberships_via_user.organization ?= @request.auth.current_organization &&
 (@request.auth.memberships_via_user.role ?= "owner" || @request.auth.memberships_via_user.role ?= "admin"))
  ||
  // Member: inventory fields only (name, description, location, metadata,
  // floorplan_position). Attaching an identity is an admin action.
  ((@request.auth.memberships_via_user.organization ?= @request.auth.current_organization &&
   (@request.auth.memberships_via_user.role ?= "owner" ||
    @request.auth.memberships_via_user.role ?= "admin" ||
    @request.auth.memberships_via_user.role ?= "member")) &&
   @request.body.nats_user:changed = false &&
   @request.body.nebula_host:changed = false &&
   @request.body.active:changed = false)
)

updateRule:
// 1. Only users can update things.
// 2. The thing must belong to the user's current organization.
// 3. The organization field cannot be modified (no "teleporting" between orgs).
// 4. nats_user / nebula_host are owner/admin only: a Thing can read the
//    credential of its own linked identity, so a member able to re-point those
//    relations at a privileged identity and then authenticate as the Thing would
//    have a credential-theft path.
// 5. active is owner/admin only for the same reason delete is: flipping it
//    revokes the Thing's NATS identity and kills its outstanding auth tokens
//    (hooks/active_flag.go). A member who could clear it could take any device in
//    the organization off the network.
// 6. The member branch names the roles it admits. Restricting the FIELDS without
//    naming the ROLE let `dashboard` -- the least privileged role, which has no inventory
//    authority at all -- create and edit Things.
@request.auth.collectionName = "users" &&
organization = @request.auth.current_organization &&
@request.body.organization:changed = false &&
(
  // Owner/admin: may assign the NATS / Nebula identity links.
  (@request.auth.memberships_via_user.organization ?= @request.auth.current_organization &&
 (@request.auth.memberships_via_user.role ?= "owner" || @request.auth.memberships_via_user.role ?= "admin"))
  ||
  // Member: inventory fields only (name, description, location, metadata,
  // floorplan_position). Attaching an identity is an admin action.
  ((@request.auth.memberships_via_user.organization ?= @request.auth.current_organization &&
   (@request.auth.memberships_via_user.role ?= "owner" ||
    @request.auth.memberships_via_user.role ?= "admin" ||
    @request.auth.memberships_via_user.role ?= "member")) &&
   @request.body.nats_user:changed = false &&
   @request.body.nebula_host:changed = false &&
   @request.body.active:changed = false)
)

deleteRule:
// Owner/admin only. `things` was the sole collection left with a member-level
// delete -- locations, thing_types, location_types, message_schemas,
// thing_type_operations, leaf_nodes, nats_roles and nebula_networks all gate it.
//
// Deleting a Thing is high-impact and not undoable from the UI: it orphans any
// NATS or Nebula identity attached to it, and leaf-sync propagates the deletion
// into every edge node local KV mirror. Members create and edit inventory;
// removing it is a management action.
@request.auth.collectionName = "users" &&
organization = @request.auth.current_organization &&
(@request.auth.memberships_via_user.organization ?= @request.auth.current_organization &&
 (@request.auth.memberships_via_user.role ?= "owner" || @request.auth.memberships_via_user.role ?= "admin"))

authRule:
// A deactivated Thing cannot obtain a new auth token.
//
// This rule is evaluated at the AUTH ENDPOINT ONLY (apis/record_helpers.go,
// RecordAuthResponse) -- not on every request carrying an already-issued token.
// authToken.duration below is 7 days, so on its own this rule would leave a
// deactivated device connected for up to a week. hooks/active_flag.go closes
// that window by refreshing tokenKey when active goes true -> false, which
// invalidates every outstanding token immediately, and by revoking the linked
// NATS identity -- which is the Thing's real capability, and is not touched by
// anything PocketBase does.
active = true

manageRule:
// Org Admins/Owners may manage (e.g. reset the PocketBase password of) their
// organization's things. Without this, `password` on update requires
// `oldPassword` (forms/record_upsert.go) which nobody holds for a device, so a
// Thing's PocketBase credential was mint-once with no recovery short of
// deleting the record. Mirrors the leaf_nodes manageRule and the updateRule
// below.
organization = @request.auth.current_organization && 
(@request.auth.memberships_via_user.organization ?= @request.auth.current_organization && 
 (@request.auth.memberships_via_user.role ?= "owner" || @request.auth.memberships_via_user.role ?= "admin"))

listRule:
// 1. Every user can see their own record
id = @request.auth.id ||
// 2. Operators can see all users (for owner selection, user management)
@request.auth.is_operator = true ||
// 3. Org Admins/Owners can see users in their current org
(
  @request.auth.current_organization != "" &&
  @request.auth.memberships_via_user.organization ?= @request.auth.current_organization &&
  (@request.auth.memberships_via_user.role ?= "owner" || @request.auth.memberships_via_user.role ?= "admin") &&
  memberships_via_user.organization ?= @request.auth.current_organization
)

