createRule:
// Operators can create users (for org onboarding).
@request.auth.is_operator = true
||
// Anonymous self-registration -- but ONLY for an address that already has a
// pending invite. AcceptInviteView has to create the account unauthenticated
// (it cannot call /api/tenancy/accept-invite, which requires auth, until the
// account exists), so this branch must stay open. accept-invite deletes the
// invite row, so the gate closes behind itself.
// Exact-match on email, consistent with the accept-invite handler's own check.
// NOTE: enabling users.oauth2 will route first-time OAuth2 logins through this
// same rule; uninvited addresses would be rejected here.
(
  @request.auth.id = ''
  && @request.body.is_operator:isset = false
  && @collection.invites.email ?= @request.body.email
)

updateRule:
// Only your own record.
id = @request.auth.id
&&
// is_operator is NOT grantable through the API. Without this clause any
// authenticated user can PATCH themselves to platform operator, which reads
// every tenant's data (including audit_logs). Granting it is superuser
// (admin panel) or `bootstrap` CLI only -- both bypass API rules.
@request.body.is_operator:isset = false
&&
// You may only switch into an organization you are actually a member of.
(
  @request.body.current_organization:isset = false
  || @request.auth.memberships_via_user.organization ?= @request.body.current_organization
)

