updateRule:
// A membership row is never re-pointed at another organization -- that would
// move a member into a different tenant. Mirrors invites.updateRule.
@request.body.organization:changed = false
&&
(
  // 1. My OWN membership -- the operational NATS identity link only.
  //    `role` has to stay out of reach here: the bare `user = @request.auth.id`
  //    this replaces let any member PATCH their own role to "owner".
  (
    user = @request.auth.id
    && @request.body.role:isset = false
    && @request.body.user:isset = false
    && @request.body.invited_by:isset = false
  )
  ||
  // 2. I am the OWNER of the organization (checked directly on the Org record)
  organization.owner = @request.auth.id
  ||
  // 3. I am an Admin/Owner of the organization (checked via back-relation
  //    so the user/role conditions correlate to the SAME membership row).
  (
    organization.memberships_via_organization.user ?= @request.auth.id &&
    (
      organization.memberships_via_organization.role ?= "owner" ||
      organization.memberships_via_organization.role ?= "admin"
    )
  )
)

